(function colorOf(id) {
  var c = document.querySelector('[data-testid="' + id + '"]');
  if (!c) return "missing";
  var s = (c.style.backgroundColor || "").split(" ").join("");
  if (!s || s === "transparent") return "none";
  if (s.charAt(0) === "#") return s.toLowerCase();
  if (s.slice(0, 4) === "rgb(" || s.slice(0, 5) === "rgba(") {
    var body = s.slice(s.indexOf("(") + 1, s.lastIndexOf(")"));
    var p = body.split(",");
    if (p.length >= 4 && parseFloat(p[3]) === 0) return "none";
    var n = (1 << 24) + (parseInt(p[0], 10) << 16) + (parseInt(p[1], 10) << 8) + parseInt(p[2], 10);
    return "#" + n.toString(16).slice(1);
  }
  return s;
})("cell-0100")

