(function sampleStatus(opaqueAttr, transformAttr, delayMs) {
  var el = document.querySelector('[data-testid="status-message"]');
  if (!el) return false;
  el.setAttribute(opaqueAttr, "pending");
  el.setAttribute(transformAttr, "pending");
  window.setTimeout(function () {
    var cs = window.getComputedStyle(el);
    var o = parseFloat(cs.opacity || "0");
    if (isNaN(o)) o = 0;
    el.setAttribute(opaqueAttr, String(Math.round(o * 1000) / 1000));
    el.setAttribute(transformAttr, String(cs.transform || ""));
  }, delayMs);
  return true;
})("data-probe-opacity-at-600ms","data-probe-transform-at-600ms",600)

